import itertools
import networkx as nx

def get_matchings(m, n):
    # Grid graph
    G = nx.Graph()
    for r in range(m):
        for c in range(n):
            G.add_node((r, c))
    for r in range(m):
        for c in range(n - 1):
            G.add_edge((r, c), (r, c + 1))
    for r in range(m - 1):
        for c in range(n):
            G.add_edge((r, c), (r + 1, c))

    # Find all perfect matchings
    # Using networkx is_graph_matching but it doesn't give all.
    # For small grids, we can backtrack.

    def backtrack(matching, current_cells):
        if len(current_cells) == m * n:
            yield list(matching)
            return

        # Find first unmatched node
        nodes = list(G.nodes())
        for u in nodes:
            if u not in current_cells:
                # Try to match u with a neighbor
                for v in G.neighbors(u):
                    if v not in current_cells:
                        matching.add((u, v))
                        current_cells.add(u)
                        current_cells.add(v)
                        yield from backtrack(matching, current_cells)
                        current_cells.remove(u)
                        current_cells.remove(v)
                        matching.remove((u, v))
                break # Only need to match the first available node

    # Better approach: recursive search
    visited = [False] * (m * n)
    mapping = {}

    def solve(idx, current_edges):
        if idx == m * n:
            yield tuple(sorted(current_edges))
            return

        u = idx // n
        v = idx % n
        if visited[idx]:
            solve(idx + 1, current_edges)
            return

        # Try to match (u, v) with neighbors
        # Neighbors: (u, v+1), (u+1, v), (u, v-1), (u-1, v)
        neighbors = []
        if v + 1 < n: neighbors.append(((u, v+1), (u, v)))
        if u + 1 < m: neighbors.append(((u+1, v), (u, v)))
        if v - 1 >= 0: neighbors.append(((u, v-1), (u, v)))
        if u - 1 >= 0: neighbors.append(((u-1, v), (u, v)))

        # Standard backtracking: pick first free node
        pass

    # Use a simpler generator
    def gen_matchings():
        board = [[False]*n for _ in range(m)]
        res = []
        def dfs(r, c):
            if r == m:
                yield list(res)
                return
            if board[r][c]:
                dfs(r, c + 1)
                return
            # Try horizontal
            if c + 1 < n and not board[r][c+1]:
                board[r][c] = True
                board[r][c+1] = True
                res.append(((r,c), (r, c+1)))
                yield from dfs(r, c + 2)
                board[r][c] = False
                board[r][c+1] = False
                res.pop()
            # Try vertical
            if r + 1 < m and not board[r+1][c]:
                board[r][c] = True
                board[r+1][c] = True
                res.append(((r,c), (r+1, c)))
                yield from dfs(r + 1, c)
                board[r][c] = False
                board[r+1][c] = False
                res.pop()
        yield from dfs(0, 0)

    return list(gen_matchings())

def solve_min_k(m, n):
    matchings = get_matchings(m, n)
    if not matchings:
        return 0

    # Convert matchings to frozensets of frozensets for hashing/comparison
    ms = [frozenset(frozenset(e) for e in m) for m in matchings]

    num_cells = m * n
    # Try k from 1 to num_cells // 2
    for k in range(1, num_cells // 2 + 1):
        # Iterate subsets of size k
        # Optimization: skip if k is too large? No.
        # For 2x4, 16 cells, C(16, 8) is huge.
        # We need to be smart.
        # But for 2x3, 6 cells, C(6,3)=20.
        # For 2x4, 8 cells, C(8,4)=70.

