        for subset in itertools.combinations(cells, k):
            M = set(subset)
            count = 0
            for matching in ms:
                valid = True
                for e in matching:
                    if e[0] in M and e[1] in M:
                        valid = False
                        break
                if valid:
                    count += 1
            if count == 1:
                return k
    return None

