import math

def get_prime_factors(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def h_value(n):
    """Compute h(n) = g(n)/n using multiplicative property"""
    factors = get_prime_factors(n)
    result = 1
    for p, k in factors.items():
        # h(p^k) = (p*k + p - k) / p = k + 1 - k/p
        numerator = p * k + p - k
        denominator = p
        result *= numerator / denominator
    return result

def find_int_values(limit):
    int_vals = {}
    examples = {}
    for n in range(1, limit + 1):
        h_val = h_value(n)
        if h_val.is_integer():
            val = int(h_val)
            int_vals[val] = int_vals.get(val, 0) + 1
            if val not in examples:
                examples[val] = []
            if len(examples[val]) < 3:
                examples[val].append(n)
    return int_vals, examples

